window.products.push({"id":525907,"name":"ZWILLING J.A. Henckels Bamboo Flatware Storage Tray","category":"homeandappliances","retail price":29.95,"sale price":null,"image":"https://m.media-amazon.com/images/I/71BmeZaXx1L._AC_SL1500_.jpg","description":"Product description 35192-000 Features: -Material: Bamboo. Product Type: -Cutlery Tray. Material: -Bamboo. Dimensions: Overall Height - Top to Bottom: -14.75 Inches. Overall Width - Side to Side: -10.625 Inches. Overall Depth - Front to Back: -2.75 Inches. Overall Product Weight: -0.7 Pounds. Amazon.com This flatware caddy makes it easy to carry utensils from kitchen table to patio and back for more casual meals. The compact caddy measures 5-1/2 by 5-1/2 inches around and 10-3/8 inches tall and has the capacity for 12 five-piece place settings. Four individual compartments separate knives, spoons, salad forks, and dinner forks so utensils can be located quickly to set the table. The caddy is made of sturdy hardwood for long-lasting use. --Cristina Vaamonde","images":["https://m.media-amazon.com/images/I/71BmeZaXx1L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"ZWILLING","source_asin":"B00008AV28","category_path":"Home & Kitchen"},"sku":"BM-525907","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00008AV28","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00008AV28","price_pending":true,"merchant_ready":false});
